using DotNetDetour.DetourWays;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Threading.Tasks;

namespace DotNetDetour
{
    public class DetourFactory
    {
        public static IDetour CreateDetourEngine()
        {
            string detourEngineType = Environment.GetEnvironmentVariable("DETOUR_ENGINE_TYPE");
            if (!string.IsNullOrEmpty(detourEngineType))
            {
                switch (detourEngineType.ToLower())
                {
                    case "32bit":
                        return new NativeDetourFor32Bit();
                    case "64bit":
                        return new NativeDetourFor64Bit();
                    default:
                        throw new NotImplementedException("Unsupported detour engine type: " + detourEngineType);
                }
            }
            else
            {
                if (IntPtr.Size == 4)
                {
                    return new NativeDetourFor32Bit();
                }
                else if (IntPtr.Size == 8)
                {
                    return new NativeDetourFor64Bit();
                }
                else
                {
                    throw new NotImplementedException();
                }
            }
        }
    }
}

