            {
                entry.ForegroundColor = foregroundColor;
                entry.BackgroundColor = backgroundColor;
                return entry;
            }

            var documents = new List<PwDocument>(new[]
            {
                new PwDocument().New().WithTotpEnabledEntries(1, ApplyColor).WithTotpEnabledEntries(1)
            });

