                    triangles[vertexIndex++] = (i0 + 0) * axis1Vertices + (i1 + 1);
                    triangles[vertexIndex++] = (i0 + 1) * axis1Vertices + (i1 + 1);
                }
            }

            var mesh = new Mesh()
            {
                name = $"Plane_{axis0Vertices}x{axis1Vertices}",
                vertices = vertices,
                normals = normals,
                uv = uvs,
                triangles = triangles
            };

            mesh.RecalculateBounds();
            return mesh;
        }
    }
