                retrievedCsrs.Any(x => x.Id == generatedCsr.Id).Should().BeFalse();
            }
            finally
            {
                await _idpApi.DeactivateIdentityProviderAsync(createdIdp.Id);
                await _idpApi.DeleteIdentityProviderAsync(createdIdp.Id);
            }
        }

