using Newtonsoft.Json;
using Newtonsoft.Json.Converters;

namespace ApiCheck.Description
{
    [JsonConverter(typeof(StringEnumConverter))]
    public enum MemberKind
    {
        Constructor,
        // This includes property and events accessors.
        Method,
        Field
    }
