        public const string SaltyChat_VoiceRange = "SaltyChat_VoiceRange";
        public const string SaltyChat_IsAlive = "SaltyChat_IsAlive";
        public const string SaltyChat_IsUsingMegaphone = "SaltyChat_IsUsingMegaphone";
        #endregion

