    private void RefreshAll()
    {
        SnackMachines = _snackMachineRepository.GetSnackMachineList();
        Atms = _atmRepository.GetAtmList();

        Notify(nameof(Atms));
        Notify(nameof(SnackMachines));
        Notify(nameof(HeadOffice));
