using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

using SharpDisasm.Helpers;

namespace SharpDisasm.Udis86
{
    /// <summary>
    /// <para>The C# udis86 library ported from C.</para>
    /// <para>For more information about how to use the C-based library see the udis86 project on GitHub https://github.com/vmt/udis86 </para>
    /// <para>This static class is thread safe ONLY WHEN using separate <see cref="ud"/> instances.</para>
    /// </summary>
    /// <remarks>This class is deliberately written to match as closely as possible to the original C-library.</remarks>
    public static class udis86
    {
        static Decode decode = new Decode();

        /* =============================================================================
         * ud_init
         *    Initializes ud_t object.
         * =============================================================================
         */
        /// <summary>
        /// Initializes ud_t object.
        /// </summary>
        /// <param name="u"></param>
        public static void
        ud_init(ref ud u)
        {
            u = new ud();
            ud_set_mode(ref u, 16);
            u.mnemonic = ud_mnemonic_code.UD_Iinvalid;
            ud_set_pc(ref u, 0);
            //#ifndef __UD_STANDALONE__
            //  ud_set_input_file(u, stdin);
            //#endif /* __UD_STANDALONE__ */

            ud_set_asm_buffer(ref u, u.asm_buf_int, u.asm_buf_int.Length);
        }


        /* =============================================================================
         * ud_disassemble
         *    Disassembles one instruction and returns the number of
         *    bytes disassembled. A zero means end of disassembly.
         * =============================================================================
         */
        /// <summary>
        /// Disassembles one instruction and returns the number of bytes disassembled. A zero means end of disassembly.
        /// </summary>
        /// <param name="u"></param>
        /// <returns></returns>
        public static int
        ud_disassemble(ref ud u)
        {
            int len;
            if (u.inp_end > 0)
            {
                return 0;
            }
            if ((len = decode.ud_decode(ref u)) > 0)
            {
                if (u.translator != null)
                {
                    for (var i = 0; i < u.asm_buf.Length; i++)
                        u.asm_buf[i] = '\0';
                    u.translator(ref u);
                }
            }
            return len;
        }


        /* =============================================================================
         * ud_set_mode() - Set Disassemly Mode.
         * =============================================================================
         */
        /// <summary>
        /// Set Disassembly mode
        /// </summary>
        /// <param name="u"></param>
        /// <param name="m"></param>
        public static void ud_set_mode(ref ud u, byte m)
        {
            switch (m)
            {
                case 16:
                case 32:
                case 64: u.dis_mode = m; return;
                default: u.dis_mode = 16; return;
            }
        }

        /* =============================================================================
         * ud_set_vendor() - Set vendor.
         * =============================================================================
         */
        /// <summary>
        /// Set vendor.
        /// </summary>
        /// <param name="u"></param>
        /// <param name="v"></param>
        public static void
        ud_set_vendor(ref ud u, int v)
        {
            switch (v)
            {
                case Decode.UD_VENDOR_INTEL:
                    u.vendor = Decode.UD_VENDOR_INTEL;
                    break;
                case Decode.UD_VENDOR_ANY:
                    u.vendor = Decode.UD_VENDOR_ANY;
                    break;
                default:
                    u.vendor = Decode.UD_VENDOR_AMD;
                    break;
            }
        }

        /* =============================================================================
         * ud_set_pc() - Sets code origin.
         * =============================================================================
         */
        /// <summary>
        /// Set code origin address
        /// </summary>
        /// <param name="u"></param>
        /// <param name="o"></param>
        public static void
        ud_set_pc(ref ud u, ulong o)
        {
            u.pc = o;
        }

        /* =============================================================================
         * ud_set_syntax() - Sets the output syntax.
         * =============================================================================
         */
        /// <summary>
        /// Sets the output syntax
        /// </summary>
        /// <param name="u"></param>
        /// <param name="t"></param>
        public static void
        ud_set_syntax(ref ud u, UdTranslatorDelegate t)
        {
            u.translator = t;
        }

        /* =============================================================================
         * ud_insn() - returns the disassembled instruction
         * =============================================================================
         */
        /// <summary>
        /// returns the disassembled instruction
        /// </summary>
        /// <param name="u"></param>
        /// <returns></returns>
        public static string ud_insn_asm(ref ud u)
        {
            if (u.asm_buf == null || u.asm_buf.Length == 0)
                return String.Empty;

            int count = Array.IndexOf<char>(u.asm_buf, '\0', 0);
            if (count < 0) count = u.asm_buf.Length;

            char[] c = new char[count];
            Array.Copy(u.asm_buf, c, count);

            return new String(c);
        }

        /* =============================================================================
         * ud_insn_offset() - Returns the offset.
         * =============================================================================
         */
        static ulong
        ud_insn_off(ref ud u)
        {
            return u.insn_offset;
        }


        /* =============================================================================
         * ud_insn_hex() - Returns hex form of disassembled instruction.
         * =============================================================================
         */
        static string
        ud_insn_hex(ref ud u)
        {
            var src_hex = new StringBuilder();

            if (u.error == 0)
            {
                int i;
                var src_ptr = ud_insn_ptr(ref u);
                unsafe
                {
                    for (i = 0; i < ud_insn_len(ref u); i++)
                    {
                        src_hex.AppendFormat("{0:2X", src_ptr[i]);
                    }
                }
            }
            return src_hex.ToString();
        }


        /* =============================================================================
         * ud_insn_ptr
         *    Returns a pointer to buffer containing the bytes that were
         *    disassembled.
         * =============================================================================
         */
        /// <summary>
        /// Returns a pointer to buffer containing the bytes that were disassembled.
        /// </summary>
        /// <param name="u"></param>
        /// <returns></returns>
        static unsafe IAssemblyCode
        ud_insn_ptr(ref ud u)
        {
            return new AssemblyCodeOffset(u.inp_buf, u.inp_buf_index - u.inp_ctr);
        }


        /* =============================================================================
         * ud_insn_len
         *    Returns the count of bytes disassembled.
         * =============================================================================
         */
        /// <summary>
        /// Returns the count of bytes disassembled.
        /// </summary>
        /// <param name="u"></param>
        /// <returns></returns>
        public static int ud_insn_len(ref ud u)
        {
            return u.inp_ctr;
        }


        /* =============================================================================
         * ud_insn_get_opr
         *    Return the operand struct representing the nth operand of
         *    the currently disassembled instruction. Returns NULL if
         *    there's no such operand.
         * =============================================================================
         */
        /// <summary>
        /// Return the operand struct representing the nth operand of
        /// the currently disassembled instruction. Returns NULL if
        /// there's no such operand.
        /// </summary>
        /// <param name="u"></param>
        /// <param name="n"></param>
        /// <param name="op"></param>
        public static void
        ud_insn_opr(ref ud u, int n, out ud_operand? op)
        {
            if (n > 3 || u.operand[n].type == ud_type.UD_NONE)
            {
                op = null;
            }
            else
            {
                op = u.operand[n];
            }
        }


        /* =============================================================================
         * ud_opr_is_sreg
         *    Returns non-zero if the given operand is of a segment register type.
         * =============================================================================
         */
        /// <summary>
        /// Returns true if the given operand is of a segment register type.
        /// </summary>
        /// <param name="opr"></param>
        /// <returns></returns>
        public static bool
        ud_opr_is_sreg(ref ud_operand opr)
        {
            return opr.type == ud_type.UD_OP_REG &&
                   opr.@base >= ud_type.UD_R_ES &&
                   opr.@base <= ud_type.UD_R_GS;
        }


        /* =============================================================================
         * ud_opr_is_sreg
         *    Returns non-zero if the given operand is of a general purpose
         *    register type.
         * =============================================================================
         */
        /// <summary>
        /// Returns true if the given operand is of a general purpose
        /// register type.
        /// </summary>
        /// <param name="opr"></param>
        /// <returns></returns>
        public static bool
        ud_opr_is_gpr(ref ud_operand opr)
        {
            return opr.type == ud_type.UD_OP_REG &&
                   opr.@base >= ud_type.UD_R_AL &&
                   opr.@base <= ud_type.UD_R_R15;
        }

        /* =============================================================================
         * ud_set_asm_buffer
         *    Allow the user to set an assembler output buffer. If `buf` is NULL,
         *    we switch back to the internal buffer.
         * =============================================================================
         */
        static void ud_set_asm_buffer(ref ud u, char[] buf, int size)
        {
            if (buf == null)
            {
                ud_set_asm_buffer(ref u, u.asm_buf_int, u.asm_buf_int.Length);
            }
            else
            {
                u.asm_buf = buf;
                u.asm_buf_size = size;
            }
        }


        /* =============================================================================
         * ud_set_sym_resolver
         *    Set symbol resolver for relative targets used in the translation
         *    phase.
         *
         *    The resolver is a function that takes a ulong address and returns a
         *    symbolic name for the that address. The function also takes a second
         *    argument pointing to an integer that the client can optionally set to a
         *    non-zero value for offsetted targets. (symbol+offset) The function may
         *    also return NULL, in which case the translator only prints the target
         *    address.
         *
         *    The function pointer maybe NULL which resets symbol resolution.
         * =============================================================================
         */
        static void
        ud_set_sym_resolver(ref ud u, UdSymbolResolverDelegate resolver)
        {
            u.sym_resolver = resolver;
        }


        /* =============================================================================
         * ud_insn_mnemonic
         *    Return the current instruction mnemonic.
         * =============================================================================
         */
        static ud_mnemonic_code
        ud_insn_mnemonic(ref ud u)
        {
            return u.mnemonic;
        }


        /* =============================================================================
         * ud_lookup_mnemonic
         *    Looks up mnemonic code in the mnemonic string table.
         *    Returns NULL if the mnemonic code is invalid.
         * =============================================================================
         */
        /// <summary>
        /// Looks up mnemonic code in the mnemonic string table.
        /// Returns NULL if the mnemonic code is invalid.
        /// </summary>
        /// <param name="c"></param>
        /// <returns></returns>
        public static string
        ud_lookup_mnemonic(ud_mnemonic_code c)
        {
            if (c < ud_mnemonic_code.UD_MAX_MNEMONIC_CODE)
            {
                return InstructionTables.ud_mnemonics_str[(int)c];
            }
            else
            {
                return null;
            }
        }


        /*
         * ud_inp_init
         *    Initializes the input system.
         */
        static unsafe void
        ud_inp_init(ref ud u)
        {
            //u.inp_buf = null;
            //u.inp_buf_index = 0;
            u.inp_curr = 0;
            u.inp_ctr = 0;
            u.inp_end = 0;
            u.inp_peek = Decode.UD_EOI;
            //UD_NON_STANDALONE(u.inp_file = NULL);
        }

        /* =============================================================================
         * ud_inp_set_buffer
         *    Set buffer as input.
         * =============================================================================
         */
        /// <summary>
        /// Set the buffer as input
        /// </summary>
        /// <param name="u">The u.</param>
        /// <param name="code">The code.</param>
        public static unsafe void ud_set_input_buffer(ref ud u, IAssemblyCode code)
        {
            ud_inp_init(ref u);
            u.inp_buf = code;
            u.inp_buf_index = 0;
        }

        /* =============================================================================
         * ud_input_skip
         *    Skip n input bytes.
         * ============================================================================
         */
        static unsafe void ud_input_skip(ref ud u, int n)
        {
            if (u.inp_end > 0)
            {
                return;
            }

            if (n > u.inp_buf_size ||
                u.inp_buf_index > u.inp_buf_size - n)
            {
                u.inp_buf_index = u.inp_buf_size;
                goto eoi;
            }
            u.inp_buf_index += n;
            return;
        eoi:
            u.inp_end = 1;
            u.error = 1;
            u.errorMessage = "cannot skip, eoi received\b";
            return;
        }


        /* =============================================================================
         * ud_input_end
         *    Returns non-zero on end-of-input.
         * =============================================================================
         */
        static int ud_input_end(ref ud u)
        {
            return u.inp_end;
        }
    }
}

'SharpDisasm/SharpDisasm.Tests/Decode32bitTests.cs'
:﻿using System;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using System.Diagnostics;
using SharpDisasm.Udis86;

#pragma warning disable 1591
namespace SharpDisasm.Tests
{
    [TestClass]
    public class Decode32bitTests
    {
        [TestInitialize]
        public void Initialise()
        {
        }

        [TestMethod]
        public void Decode32Test()
        {
            Disassembler.Translator.IncludeAddress = false;
            Disassembler.Translator.IncludeBinary = false;

            var disasm = new Disassembler(new byte[] {
                0xb8, 0x34, 0x12, 0x00, 0x00,   // mov eax, 0x1234
                0xa1, 0x34, 0x12, 0x00, 0x00,   // mov eax, [0x1234]
                0x89, 0x45, 0xEC,               // mov [ebp-0x14], eax
                0x83, 0xe2, 0xdf,               // and edx, 0xffffffdf
            }, ArchitectureMode.x86_32);

            var insn = disasm.NextInstruction();
            Assert.AreEqual("mov eax, 0x1234", insn.ToString());
            Assert.AreEqual(5, insn.Length);

            insn = disasm.NextInstruction();
            Assert.AreEqual("mov eax, [0x1234]", insn.ToString());
            Assert.AreEqual(5, insn.Length);

            insn = disasm.NextInstruction();
            Assert.AreEqual("mov [ebp-0x14], eax", insn.ToString());

            insn = disasm.NextInstruction();
            Assert.AreEqual("and edx, 0xffffffdf", insn.ToString());
        }

        [TestMethod]
        public void Corner32Test()
        {
            Disassembler.Translator.IncludeAddress = false;
            Disassembler.Translator.IncludeBinary = false;

            var disasm = new Disassembler(new byte[] {
                0x67, 0x0f, 0x02, 0x00,
                0x90,
                0xf3, 0x90
            }, ArchitectureMode.x86_32);
            //0000000000000000 670f0200         lar eax, word [bx+si]
            //0000000000000004 90               nop
            //0000000000000005 f390             pause

            var insn = disasm.NextInstruction();
            Assert.AreEqual("lar eax, word [bx+si]", insn.ToString());
            Assert.AreEqual(4, insn.Length);

            insn = disasm.NextInstruction();
            Assert.AreEqual("nop", insn.ToString());
            Assert.AreEqual(1, insn.Length);

            insn = disasm.NextInstruction();
            Assert.AreEqual("pause", insn.ToString());
            Assert.AreEqual(2, insn.Length);
        }

        [TestMethod]
        public void InvalidSeg32Test()
        {
            var disasm = new Disassembler(new byte[] {
                0x8c, 0x38
            }, ArchitectureMode.x86_32);

            var insn = disasm.NextInstruction();
            Assert.AreEqual("invalid", insn.ToString());
        }

        [TestMethod]
        public void RelativeJump32Test()
        {
            // set program counter offset
            var disasm = new Disassembler(new byte[] {
                0x90,
                0x90,
                0x90,
                0x90,
                0x90,
                0xeb, 0xf9,
                0x90,
                0x66, 0xe9, 0x0a, 0x00,
                0x90,
                0x90,
                0xe9, 0x03, 0x00, 0x00, 0x00,
                0x90,
                0x90,
                0x90,
                0x90,
                0x90,
                0xeb, 0xe6,
                0x89, 0x45, 0xEC,
            }, ArchitectureMode.x86_32, 0x80000000);
            /*
            0000000080000000 90               nop
            0000000080000001 90               nop
            0000000080000002 90               nop
            0000000080000003 90               nop
            0000000080000004 90               nop
            0000000080000005 ebf9             jmp 0x80000000
            0000000080000007 90               nop
            0000000080000008 66e90a00         jmp 0x16
            000000008000000c 90               nop
            000000008000000d 90               nop
            000000008000000e e903000000       jmp 0x80000016
            0000000080000013 90               nop
            0000000080000014 90               nop
            0000000080000015 90               nop
            0000000080000016 90               nop
            0000000080000017 90               nop
            0000000080000018 ebe6             jmp 0x80000000
                * */

            var insn = disasm.NextInstruction();
            Assert.AreEqual("nop", insn.ToString());
            insn = disasm.NextInstruction();
            Assert.AreEqual("nop", insn.ToString());
            insn = disasm.NextInstruction();
            Assert.AreEqual("nop", insn.ToString());
            insn = disasm.NextInstruction();
            Assert.AreEqual("nop", insn.ToString());
            insn = disasm.NextInstruction();
            Assert.AreEqual("nop", insn.ToString());

            insn = disasm.NextInstruction();
            Assert.AreEqual("jmp 0x80000000", insn.ToString());

            insn = disasm.NextInstruction();
            Assert.AreEqual("nop", insn.ToString());

            insn = disasm.NextInstruction();
            Assert.AreEqual("jmp 0x16", insn.ToString());

            insn = disasm.NextInstruction();
            Assert.AreEqual("nop", insn.ToString());
            insn = disasm.NextInstruction();
            Assert.AreEqual("nop", insn.ToString());

            insn = disasm.NextInstruction();
            Assert.AreEqual("jmp 0x80000016", insn.ToString());

            insn = disasm.NextInstruction();
            Assert.AreEqual("nop", insn.ToString());
            insn = disasm.NextInstruction();
            Assert.AreEqual("nop", insn.ToString());
            insn = disasm.NextInstruction();
            Assert.AreEqual("nop", insn.ToString());
            insn = disasm.NextInstruction();
            Assert.AreEqual("nop", insn.ToString());
            insn = disasm.NextInstruction();
            Assert.AreEqual("nop", insn.ToString());

            insn = disasm.NextInstruction();
            Assert.AreEqual("jmp 0x80000000", insn.ToString());
        }

        [TestMethod]
        public void Obscure32Test()
        {
            var disasm = new Disassembler(new byte[] {
                0xd1, 0xf6,
                0xd0, 0xf6,
                0xd9, 0xd9,
                0xdc, 0xd0,
                0xdc, 0xd8,
                0xdd, 0xc8,
                0xde, 0xd1,
                0xdf, 0xc3,
                0xdf, 0xd0,
                0xdf, 0xd8,
            }, ArchitectureMode.x86_32);
            //0000000000000000 d1f6             shl esi, 1
            //0000000000000002 d0f6             shl dh, 1
            //0000000000000004 d9d9             fstp1 st1
            //0000000000000006 dcd0             fcom2 st0
            //0000000000000008 dcd8             fcomp3 st0
            //000000000000000a ddc8             fxch4 st0
            //000000000000000c ded1             fcomp5 st1
            //000000000000000e dfc3             ffreep st3
            //0000000000000010 dfd0             fstp8 st0
            //0000000000000012 dfd8             fstp9 st0
            //0000000000000014 83e2df           and edx, 0xffffffdf

            var insn = disasm.NextInstruction();
            Assert.AreEqual("shl esi, 1", insn.ToString());

            insn = disasm.NextInstruction();
            Assert.AreEqual("shl dh, 1", insn.ToString());

            insn = disasm.NextInstruction();
            Assert.AreEqual("fstp1 st1", insn.ToString());

            insn = disasm.NextInstruction();
            Assert.AreEqual("fcom2 st0", insn.ToString());

            insn = disasm.NextInstruction();
            Assert.AreEqual("fcomp3 st0", insn.ToString());

            insn = disasm.NextInstruction();
            Assert.AreEqual("fxch4 st0", insn.ToString());

            insn = disasm.NextInstruction();
            Assert.AreEqual("fcomp5 st1", insn.ToString());

            insn = disasm.NextInstruction();
            Assert.AreEqual("ffreep st3", insn.ToString());

            insn = disasm.NextInstruction();
            Assert.AreEqual("fstp8 st0", insn.ToString());

            insn = disasm.NextInstruction();
            Assert.AreEqual("fstp9 st0", insn.ToString());
        }

        [TestMethod]
        public void DecodeNotFromZero()
        {
            Disassembler.Translator.IncludeAddress = false;
            Disassembler.Translator.IncludeBinary = false;

            var disasm = new Disassembler(new byte[] {
                0xb8, 0x34, 0x12, 0x00, 0x00,   // mov eax, 0x1234
                0x83, 0xe2, 0xdf,               // and edx, 0xffffffdf
            }, ArchitectureMode.x86_32, offset: 5);

            var insn = disasm.NextInstruction();
            Assert.AreEqual("and edx, 0xffffffdf", insn.ToString());
        }
    }
