public interface IAuthorizationRepository
{
    UsersGroup CreateUsersGroup(string name);
    void AssociateUserWith(IUser user, string groupName);
    UsersGroup[] GetAssociatedUsersGroupFor(IUser user);
}

public class AuthorizationRepository : IAuthorizationRepository
{
    private readonly ISession session;

    public AuthorizationRepository(ISession session)
    {
        this.session = session;
    }

    public UsersGroup CreateUsersGroup(string name)
    {
        var group = new UsersGroup { Name = name };
        session.Save(group);
        return group;
    }

    public void AssociateUserWith(IUser user, string groupName)
    {
        var group = GetUsersGroupByName(groupName);
        group.Users.Add(user);
        if (group.UserAssociationCount.ContainsKey(user.Id))
        {
            group.UserAssociationCount[user.Id]++;
        }
        else
        {
            group.UserAssociationCount[user.Id] = 1;
        }
        session.SaveOrUpdate(group);
    }

    public UsersGroup[] GetAssociatedUsersGroupFor(IUser user)
    {
        return session.CreateCriteria(typeof(UsersGroup))
            .CreateAlias("Users", "u")
            .Add(Restrictions.Eq("u.Id", user.Id))
            .List<UsersGroup>()
            .ToArray();
    }

    public UsersGroup GetUsersGroupByName(string name)
    {
        return session.CreateCriteria(typeof(UsersGroup))
            .Add(Restrictions.Eq("Name", name))
            .UniqueResult<UsersGroup>();
    }
}

