:﻿using GeodesicGrid;
using System.Linq;
using UnityEngine;

namespace Kethane.UserInterface
{
    [KSPAddon(KSPAddon.Startup.MainMenu, false)]
    internal class MainMenuOverlay : MonoBehaviour
    {
        protected void Start()
        {
            var overlayRenderer = gameObject.AddComponent<OverlayRenderer>();
            overlayRenderer.SetGridLevel(KethaneData.GridLevel);
            overlayRenderer.IsVisible = startMenuOverlay(overlayRenderer);
        }

        private bool startMenuOverlay(OverlayRenderer overlayRenderer)
        {
            if (!Misc.Parse(SettingsManager.GetValue("ShowInMenu"), true)) { return false; }

            var objects = GameObject.FindObjectsOfType(typeof(GameObject));
            if (objects.Any(o => o.name == "LoadingBuffer")) { return false; }
            var kerbin = objects.OfType<GameObject>().Where(b => b.name == "Kerbin").LastOrDefault();

            if (kerbin == null)
            {
                Debug.LogWarning("[Kethane] Couldn't find Kerbin!");
                return false;
            }

            overlayRenderer.SetTarget(kerbin.transform);
            overlayRenderer.SetRadiusMultiplier(1.02f);

            var random = new System.Random();
            var colors = new CellMap<Color32>(KethaneData.GridLevel);

            foreach (var cell in Cell.AtLevel(KethaneData.GridLevel))
            {
                var rand = random.Next(100);
                Color32 color;
                if (rand < 16)
                {
                    color = rand < 4 ? new Color32(21, 176, 26, 255) : new Color32(128, 128, 128, 192);
                    foreach (var neighbor in cell.GetNeighbors(KethaneData.GridLevel))
                    {
                        if (random.Next(2) < 1)
                        {
                            colors[neighbor] = color;
                        }
                    }
                }
                else
                {
                    color = new Color32(0, 0, 0, 128);
                }

                colors[cell] = color;
            }

            overlayRenderer.SetCellColors(colors);

            return true;
        }
    }
}

'Kethane/Plugin/Kethane/PartModules/KethaneExtractor.cs'
:﻿using GeodesicGrid;
using Kethane.UserInterface;
using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;

namespace Kethane.PartModules
{
    public class KethaneExtractor : PartModule
    {
        public class Resource
        {
            public string Name { get; private set; }
            public float Rate { get; private set; }

            public Resource(ConfigNode node)
            {
                Name = node.GetValue("Name");
                Rate = float.Parse(node.GetValue("Rate"));
            }
        }

        private class DefaultExtractorAnimator : IExtractorAnimator
        {
            public ExtractorState CurrentState { get; private set; }
            public void Deploy() { CurrentState = ExtractorState.Deployed; }
            public void Retract() { CurrentState = ExtractorState.Retracted; }

            public DefaultExtractorAnimator()
            {
                CurrentState = ExtractorState.Retracted;
            }
        }

        private IExtractorAnimator animator;

        private List<Resource> resources;

        [KSPField(isPersistant = false)]
        public float PowerConsumption;

        [KSPField(isPersistant = false, guiActive = true, guiName = "Status")]
        public string Status;

        [KSPField(isPersistant = false)]
        public string HeadTransform;

        [KSPField(isPersistant = false)]
        public string TailTransform;

        [KSPField(isPersistant = false)]
        public float HeadOffset;

        [KSPField(isPersistant = false)]
        public float TailOffset;

        public ConfigNode config;

        private Transform headTransform;
        private Transform tailTransform;

        private KethaneParticleEmitter[] emitters;

        public override void OnStart(PartModule.StartState state)
        {
            this.part.force_activate();
            animator = part.Modules.OfType<IExtractorAnimator>().SingleOrDefault();

            if (animator == null)
            {
                animator = new DefaultExtractorAnimator();
            }
            else
            {
                Events["DeployDrill"].guiActiveEditor = true;
                Events["RetractDrill"].guiActiveEditor = true;
            }

            headTransform = this.part.FindModelTransform(HeadTransform);
            tailTransform = this.part.FindModelTransform(TailTransform);

            if (state == StartState.Editor) { return; }
            if (FlightGlobals.fetch == null) { return; }

            emitters = part.Modules.OfType<KethaneParticleEmitter>().ToArray();

            foreach (var emitter in emitters)
            {
                emitter.Setup();
                emitter.EmitterTransform.parent = headTransform;
                emitter.EmitterTransform.localRotation = Quaternion.identity;
            }
        }

        public override void OnLoad(ConfigNode config)
        {
            if (this.config == null)
            {
                this.config = new ConfigNode();
                config.CopyTo(this.config);
            }

            resources = this.config.GetNodes("Resource").Select(n => new Resource(n)).ToList();
        }

        [KSPEvent(guiActive = true, guiName = "Deploy Drill", active = true, externalToEVAOnly = true, guiActiveUnfocused = true, unfocusedRange = 1.5f)]
        public void DeployDrill()
        {
            animator.Deploy();
        }

        [KSPEvent(guiActive = true, guiName = "Retract Drill", active = false, externalToEVAOnly = true, guiActiveUnfocused = true, unfocusedRange = 1.5f)]
        public void RetractDrill()
        {
            animator.Retract();
        }

        [KSPAction("Deploy Drill")]
        public void DeployDrillAction(KSPActionParam param)
        {
            DeployDrill();
        }

        [KSPAction("Retract Drill")]
        public void RetractDrillAction(KSPActionParam param)
        {
            RetractDrill();
        }

        [KSPAction("Toggle Drill")]
        public void ToggleDrillAction(KSPActionParam param)
        {
            if (animator.CurrentState == ExtractorState.Deployed || animator.CurrentState == ExtractorState.Deploying)
            {
                RetractDrill();
            }
            else if (animator.CurrentState == ExtractorState.Retracted || animator.CurrentState == ExtractorState.Retracting)
            {
                DeployDrill();
            }
        }

        public override string GetInfo()
        {
            return String.Concat(resources.Select(r => String.Format("{0} Rate: {1:F2}L/s\n", r.Name, r.Rate)).ToArray()) + String.Format("Power Consumption: {0:F2}/s", PowerConsumption);
        }

        public void Update()
        {
            var retracted = (animator.CurrentState == ExtractorState.Retracted);
            var deployed = (animator.CurrentState == ExtractorState.Deployed);
            if (Events["DeployDrill"].active != retracted || Events["RetractDrill"].active != deployed)
            {
                Events["DeployDrill"].active = retracted;
                Events["RetractDrill"].active = deployed;
                foreach (var window in GameObject.FindObjectsOfType(typeof(UIPartActionWindow)).OfType<UIPartActionWindow>().Where(w => w.part == part))
                {
                    window.displayDirty = true;
                }
            }
            Status = animator.CurrentState.ToString();

            if (!HighLogic.LoadedSceneIsFlight) { return; }

            if (animator.CurrentState != ExtractorState.Retracted)
            {
                RaycastHit hitInfo;
                var hit = raycastGround(out hitInfo);

                foreach (var emitter in emitters.Where(e => e.Label != "gas"))
                {
                    emitter.Emit = hit;
                }
                if (hit)
                {
                    foreach (var emitter in emitters)
                    {
                        emitter.EmitterPosition = headTransform.InverseTransformPoint(hitInfo.point);
                    }
                }

                foreach (var emitter in emitters.Where(e => e.Label == "gas"))
                {
                    if (animator.CurrentState == ExtractorState.Deployed)
                    {
                        emitter.Emit = hit && getBodyResources("Kethane").GetQuantity(getCellUnder()) != null;
                    }
                    else
                    {
                        emitter.Emit = false;
                    }
                }
            }
            else
            {
                foreach (var emitter in emitters)
                {
                    emitter.Emit = false;
                }
            }
        }

        public override void OnFixedUpdate()
        {
            if (animator.CurrentState != ExtractorState.Deployed) { return; }
            if (!raycastGround()) { return; }

            var energyRequest = this.PowerConsumption * TimeWarp.fixedDeltaTime;
            var energyRatio = this.part.RequestResource("ElectricCharge", energyRequest) / energyRequest;

            foreach (var resource in resources)
            {
                var cell = getCellUnder();
                var bodyResources = getBodyResources(resource.Name);
                var deposit = bodyResources.GetQuantity(cell);
                if (deposit == null) { continue; }

                double amount = TimeWarp.fixedDeltaTime * resource.Rate * energyRatio;
                amount = Math.Min(amount, deposit.Value);
                bodyResources.Extract(cell, -this.part.RequestResource(resource.Name, -amount));
            }
        }

        private Cell getCellUnder()
        {
            return MapOverlay.GetCellUnder(this.vessel.mainBody, this.vessel.transform.position);
        }

        private IBodyResources getBodyResources(string resourceName)
        {
            return KethaneData.Current[resourceName][this.vessel.mainBody].Resources;
        }

        private bool raycastGround()
        {
            RaycastHit hitInfo;
            return raycastGround(out hitInfo);
        }

        private bool raycastGround(out RaycastHit hitInfo)
        {
            var mask = 1 << 15;
            var direction = headTransform.position - tailTransform.position;
            return Physics.Raycast(tailTransform.position - direction.normalized * TailOffset, direction, out hitInfo, direction.magnitude + HeadOffset + TailOffset, mask);
        }
    }
}

'Kethane/Plugin/Kethane/Scenarios/KethaneScanningTutorial.cs'
:﻿using GeodesicGrid;
using Kethane.PartModules;
using Kethane.UserInterface;
using System;
using System.Linq;
using UnityEngine;

namespace Kethane.Scenarios
{
    public class KethaneScanningTutorial : TutorialScenario
    {
        protected override void OnAssetSetup()
        {
            instructorPrefabName = "Instructor_Gene";
        }

        private const string lockName = "KethaneScanningTutorialLock";

        private float surfaceCoverage = 0;
        private GUIStyle boldStyle = null;

        protected override void OnTutorialSetup()
        {
            TutorialPage introduction, grid, detector, sounds, colors, timewarp, conclusion;

            instructor.CharacterName = "Majiir";

            #region Introduction

            introduction = new TutorialPage("introduction");
            introduction.windowTitle = "Kethane Scanning Tutorial";

            introduction.OnEnter = s =>
            {
                instructor.StopRepeatingEmote();
            };

            introduction.OnDrawContent = () =>
            {
                GUILayout.Label("Hi there! Today we're going to use satellites to scan for Kethane, a valuable resource found all around the Kerbal system. Kethane can be processed into rocket fuel or burned in special engines, but we'll have to find it first.\n\nWe'll be controlling a Mun satellite together from here at KSC. It's been equipped with a Kethane survey unit and solar panels for power. Let's get started!");

                if (GUILayout.Button("Next")) { Tutorial.GoToNextPage(); }
            };

            Tutorial.AddPage(introduction);

            #endregion

            #region Grid

            grid = new TutorialPage("grid");
            grid.windowTitle = "Kethane Scanning Tutorial";

            grid.OnEnter = s =>
            {
                MapView.EnterMapView();
                MapOverlay.ShowOverlay = true;
                MapOverlay.SelectedResource = "Kethane";
                instructor.PlayEmote(instructor.anim_idle_lookAround);
            };

            grid.OnDrawContent = () =>
            {
                GUILayout.Label("Here we are in the map view. The cellular grid around the Mun will display resource scan data once we've collected it.\n\nYou can hide the grid or switch to other resources (if you have other resource mods installed) using the green window. (It might be hidden under this one.) The grid will appear around whatever planet or moon you're focused on, so you can view scan data from anywhere in the system.\n\nTake a moment to get comfortable with the grid controls and we'll continue when you're ready.");

                if (GUILayout.Button("Next")) { Tutorial.GoToNextPage(); }
            };

            grid.OnLeave = s =>
            {
                MapView.ExitMapView();
            };

            Tutorial.AddPage(grid);

            #endregion

            #region Detector

            detector = new TutorialPage("detector");
            detector.windowTitle = "Kethane Scanning Tutorial";

            detector.OnEnter = s =>
            {
                instructor.PlayEmote(instructor.anim_idle_wonder);
                InputLockManager.RemoveControlLock(lockName + "_actions");
            };

            detector.OnDrawContent = () =>
            {
                GUILayout.Label("Now, let's get scanning! There's a Kethane detector mounted on the front of the satellite. Right-click it and click \"Activate Detector\" to begin scanning.");
            };

            detector.OnFixedUpdate = () =>
            {
                if (FlightGlobals.ActiveVessel.Parts.SelectMany(p => p.Modules.OfType<KethaneDetector>()).Any(d => d.IsDetecting))
                {
                    Tutorial.GoToNextPage();
                }
            };

            detector.OnLeave = s =>
            {
                InputLockManager.SetControlLock(ControlTypes.ACTIONS_SHIP, lockName + "_actions");
                MapView.ExitMapView();
            };

            Tutorial.AddPage(detector);

            #endregion

            #region Sounds

            sounds = new TutorialPage("sounds");
            sounds.windowTitle = "Kethane Scanning Tutorial";

            sounds.OnEnter = s =>
            {
                instructor.PlayEmote(instructor.anim_true_thumbsUp);
                InputLockManager.RemoveControlLock(lockName + "_map");
            };

            sounds.OnDrawContent = () =>
            {
                GUILayout.Label("Excellent! The detector has turned toward the surface of the Mun, scanning for underground Kethane deposits. You'll occasionally hear beeping or blipping noises as the detector passes over cells on the grid. A louder tone indicates the presence of Kethane directly underneath the satellite.\n\nWhen you're ready, open the map view and we'll take a look at the results.");
            };

            sounds.OnFixedUpdate = () =>
            {
                if (MapView.MapIsEnabled)
                {
                    Tutorial.GoToNextPage();
                }
            };

            sounds.OnLeave = s =>
            {
                InputLockManager.SetControlLock(ControlTypes.MAP, lockName + "_map");
            };

            Tutorial.AddPage(sounds);

            #endregion

            #region Colors

            colors = new TutorialPage("colors");
            colors.windowTitle = "Kethane Scanning Tutorial";

            colors.OnEnter = s =>
            {
                instructor.PlayEmote(instructor.anim_idle_lookAround);
            };

            colors.OnDrawContent = () =>
            {
                GUILayout.Label("Now that we're scanning, you can see that some cells on the grid have changed color. Green cells indicate the presence of Kethane, and light gray cells have been scanned but nothing was found underneath.\n\nFor detailed information, you can hover your mouse over a cell on the grid. When you hover over a resource deposit, the quantity available for mining will also be displayed.");

                if (GUILayout.Button("Next")) { Tutorial.GoToNextPage(); }
            };

            Tutorial.AddPage(colors);

            #endregion

            #region Timewarp

            timewarp = new TutorialPage("timewarp");
            timewarp.windowTitle = "Kethane Scanning Tutorial";

            timewarp.OnEnter = s =>
            {
                instructor.PlayEmote(instructor.anim_idle_sigh);
                InputLockManager.RemoveControlLock(lockName + "_timewarp");
            };

            timewarp.OnDrawContent = () =>
            {
                if (boldStyle == null)
                {
                    boldStyle = new GUIStyle(GUI.skin.label);
                    boldStyle.fontStyle = FontStyle.Bold;
                }

                GUILayout.Label("Scanning the Mun is going to take a while at this rate. Luckily, we can send our satellite into time warp to finish the job faster. Note that while warping, the detector will lose some data, but overall it will still work faster.\n\nUse time warp to get 2% of the Mun scanned. Watch your battery levels as you approach the dark side. Detectors use a lot of power!");
                GUILayout.Label(String.Format("Surface Coverage: {0:P2}", surfaceCoverage), boldStyle);
            };

            timewarp.OnUpdate = () =>
            {
                surfaceCoverage = (float)Cell.AtLevel(KethaneData.GridLevel).Count(c => KethaneData.Current["Kethane"][FlightGlobals.currentMainBody].IsCellScanned(c)) / Cell.CountAtLevel(KethaneData.GridLevel);
                if (surfaceCoverage >= 0.02f)
                {
                    Tutorial.GoToNextPage();
                }
            };

            Tutorial.AddPage(timewarp);

            #endregion

            #region Conclusion

            conclusion = new TutorialPage("conclusion");
            conclusion.windowTitle = "Kethane Scanning Tutorial";

            conclusion.OnEnter = s =>
            {
                instructor.PlayEmoteRepeating(instructor.anim_true_smileB, 2);
                InputLockManager.RemoveControlLock(lockName + "_map");
            };

            conclusion.OnDrawContent = () =>
            {
                GUILayout.Label("Nice work! That wraps up our scanning session. Now try building a satellite of your own, or we can move onto using drills to extract Kethane from the ground. Thanks for stopping by!");

                if (GUILayout.Button("Finish")) { GameObject.Destroy(this); }
            };

            Tutorial.AddPage(conclusion);

            #endregion

            InputLockManager.SetControlLock(ControlTypes.ACTIONS_SHIP, lockName + "_actions");
            InputLockManager.SetControlLock(ControlTypes.ALL_SHIP_CONTROLS & ~ControlTypes.ACTIONS_SHIP, lockName + "_controls");
            InputLockManager.SetControlLock(ControlTypes.MAP, lockName + "_map");
            InputLockManager.SetControlLock(ControlTypes.TIMEWARP, lockName + "_timewarp");

            Tutorial.StartTutorial(introduction);
        }

        public void OnDestroy()
        {
            InputLockManager.RemoveControlLock(lockName + "_actions");
            InputLockManager.RemoveControlLock(lockName + "_controls");
            InputLockManager.RemoveControlLock(lockName + "_map");
            InputLockManager.RemoveControlLock(lockName + "_timewarp");
        }
    }
}

