        private void ConnectTimeout_Tick(object sender, EventArgs e)
        {
            Clients[] clients = GetAllClients();
            if (clients.Length > 0)
            {
                foreach (Clients client in clients)
                {
                    if (Methods.DiffSeconds(client.LastPing,DateTime.Now) > 20)
                    {
                        client.Disconnected();
                    }
                }
            }                
        }

