public class NodeCommentParser : ILineParser
{
    private const string CommentGroup = "Comment";
    private const string NodeCommentLineStarter = "CM_ NODE_";

    private readonly string m_nodeCommentLineParsingRegex = $@"CM_ NODE_ (?<{CommentGroup}>[^"]*)";

    private readonly IParseFailureObserver m_observer;
    private readonly Regex m_regex;

    public NodeCommentParser(IParseFailureObserver observer)
    {
        m_observer = observer;
        m_regex = new Regex(m_nodeCommentLineParsingRegex);
    }

    public bool TryParse(string line, IDbcBuilder builder, INextLineProvider nextLineProvider)
    {
        if (line.TrimStart().StartsWith(NodeCommentLineStarter) == false)
            return false;

        var match = m_regex.Match(line);
        if (match.Success)
        {
            var comment = match.Groups[CommentGroup].Value.Trim();
            builder.AddNodeComment(comment);
        }
        else
            m_observer.NodeCommentSyntaxError();

        return true;
    }
}

