:﻿using System.ComponentModel;
using System.Windows;
using System.Windows.Automation.Peers;
using System.Windows.Controls;

namespace WSATools.Controls
{
    /// <summary>
    /// 按照步骤 1a 或 1b 操作，然后执行步骤 2 以在 XAML 文件中使用此自定义控件。
    ///
    /// 步骤 1a) 在当前项目中存在的 XAML 文件中使用该自定义控件。
    /// 将此 XmlNamespace 特性添加到要使用该特性的标记文件的根
    /// 元素中:
    ///
    ///     xmlns:MyNamespace="clr-namespace:WSATools.Controls"
    ///
    ///
    /// 步骤 1b) 在其他项目中存在的 XAML 文件中使用该自定义控件。
    /// 将此 XmlNamespace 特性添加到要使用该特性的标记文件的根
    /// 元素中:
    ///
    ///     xmlns:MyNamespace="clr-namespace:WSATools.Controls;assembly=WSATools.Controls"
    ///
    /// 您还需要添加一个从 XAML 文件所在的项目到此项目的项目引用，
    /// 并重新生成以避免编译错误:
    ///
    ///     在解决方案资源管理器中右击目标项目，然后依次单击
    ///     “添加引用”->“项目”->[浏览查找并选择此项目]
    ///
    ///
    /// 步骤 2)
    /// 继续操作并在 XAML 文件中使用控件。
    ///
    ///     <MyNamespace:SettingsGroup/>
    ///
    /// </summary>
    /// <summary>
    /// Represents a control that can contain multiple settings (or other) controls
    /// </summary>
    [TemplateVisualState(Name = "Normal", GroupName = "CommonStates")]
    [TemplateVisualState(Name = "Disabled", GroupName = "CommonStates")]
    public partial class SettingsGroup : ItemsControl
    {
        public SettingsGroup()
        {
            DefaultStyleKey = typeof(SettingsGroup);
        }

        public static readonly DependencyProperty HeaderProperty = DependencyProperty.Register(
            "Header",
            typeof(string),
            typeof(SettingsGroup),
            new PropertyMetadata(default(string)));

        [Localizable(true)]
        public string Header
        {
            get => (string)GetValue(HeaderProperty);
            set => SetValue(HeaderProperty, value);
        }

        public override void OnApplyTemplate()
        {
            IsEnabledChanged -= SettingsGroup_IsEnabledChanged;
            SetEnabledState();
            IsEnabledChanged += SettingsGroup_IsEnabledChanged;
            base.OnApplyTemplate();
        }

        private void SettingsGroup_IsEnabledChanged(object sender, DependencyPropertyChangedEventArgs e)
        {
            SetEnabledState();
        }

        private void SetEnabledState()
        {
            VisualStateManager.GoToState(this, IsEnabled ? "Normal" : "Disabled", true);
        }

        protected override AutomationPeer OnCreateAutomationPeer()
        {
            return new SettingsGroupAutomationPeer(this);
        }
    }

    public class SettingsGroupAutomationPeer : FrameworkElementAutomationPeer
    {
        public SettingsGroupAutomationPeer(SettingsGroup owner)
            : base(owner)
        {
        }

        protected override string GetNameCore()
        {
            SettingsGroup selectedSettingsGroup = (SettingsGroup)Owner;
            return selectedSettingsGroup.Header;
        }
    }
}

'WSA-Tools/WSATools/WSATools/Pages/MainPage.xaml.cs'
:﻿using ModernWpf;
using ModernWpf.Controls;
using ModernWpf.Media.Animation;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Windows;
using System.Windows.Media;
using System.Windows.Navigation;
using WSATools.Controls;
using WSATools.Helpers;
using WSATools.Pages.SettingsPages;

namespace WSATools.Pages
{
    /// <summary>
    /// MainPage.xaml 的交互逻辑
    /// </summary>
    public partial class MainPage : Page
    {
        public PageHeader PageHeader => NavigationView.FindDescendant<PageHeader>();

        private readonly List<(string Tag, Type Page)> _pages = new()
        {
            ("Home", typeof(HomePage)),
            ("Apps", typeof(AppsPage)),
        };

        public MainPage()
        {
            InitializeComponent();
            UIHelper.MainPage = this;
            NavigationView.PaneDisplayMode = NavigationViewPaneDisplayMode.Left;
        }

        private void NavigationView_Loaded(object sender, RoutedEventArgs e)
        {
            // Add handler for ContentFrame navigation.
            NavigationViewFrame.Navigated += On_Navigated;
            NavigationView.SelectedItem = NavigationView.MenuItems[0];
            NavigationView.PaneDisplayMode = NavigationViewPaneDisplayMode.Auto;
        }

        private void NavigationView_Navigate(string NavItemTag, NavigationTransitionInfo TransitionInfo)
        {
            Type _page = null;
            if (NavItemTag == "settings")
            {
                _page = typeof(SettingsPage);
            }
            else
            {
                (string Tag, Type Page) item = _pages.FirstOrDefault(p => p.Tag.Equals(NavItemTag, StringComparison.Ordinal));
                _page = item.Page;
            }
            // Get the page type before navigation so you can prevent duplicate
            // entries in the backstack.
            Type PreNavPageType = NavigationViewFrame.CurrentSourcePageType;

            // Only navigate if the selected page isn't currently loaded.
            if (!(_page is null) && !Equals(PreNavPageType, _page))
            {
                _ = NavigationViewFrame.Navigate(_page, null, TransitionInfo);
            }
        }

        private void NavigationView_BackRequested(NavigationView sender, NavigationViewBackRequestedEventArgs args) => _ = TryGoBack();

        private void NavigationView_SelectionChanged(NavigationView sender, NavigationViewSelectionChangedEventArgs args)
        {
            if (args.IsSettingsSelected)
            {
                _ = NavigationViewFrame.Navigate(typeof(SettingsPage), null, args.RecommendedNavigationTransitionInfo);
            }
            else if (args.SelectedItemContainer != null)
            {
                string NavItemTag = args.SelectedItemContainer.Tag.ToString();
                NavigationView_Navigate(NavItemTag, args.RecommendedNavigationTransitionInfo);
            }
        }

        private bool TryGoBack()
        {
            if (!NavigationViewFrame.CanGoBack)
            { return false; }

            // Don't go back if the nav pane is overlayed.
            if (NavigationView.IsPaneOpen &&
                (NavigationView.DisplayMode == NavigationViewDisplayMode.Compact ||
                 NavigationView.DisplayMode == NavigationViewDisplayMode.Minimal))
            { return false; }

            NavigationViewFrame.GoBack();
            return true;
        }

        private void On_Navigated(object _, NavigationEventArgs e)
        {
            NavigationView.IsBackEnabled = NavigationViewFrame.CanGoBack;
            if (NavigationViewFrame.SourcePageType == typeof(SettingsPage))
            {
                // SettingsItem is not part of NavView.MenuItems, and doesn't have a Tag.
                NavigationView.SelectedItem = (NavigationViewItem)NavigationView.SettingsItem;
                NavigationView.Header = "设置";
            }
            else if (NavigationViewFrame.SourcePageType == typeof(TestPage))
            {
                NavigationView.Header = "测试";
            }
            else if (NavigationViewFrame.SourcePageType != null)
            {
                (string Tag, Type Page) item = _pages.FirstOrDefault(p => p.Page == e.Content.GetType());

                try
                {
                    NavigationView.SelectedItem = NavigationView.MenuItems
                        .OfType<NavigationViewItem>()
                        .First(n => n.Tag.Equals(item.Tag));
                }
                catch
                {
                    try
                    {
                        NavigationView.SelectedItem = NavigationView.FooterMenuItems
                            .OfType<NavigationViewItem>()
                            .First(n => n.Tag.Equals(item.Tag));
                    }
                    catch { }
                }

                NavigationView.Header = (((NavigationViewItem)NavigationView.SelectedItem)?.Content?.ToString());
            }
        }

        private void NavigationViewControl_PaneClosing(NavigationView sender, NavigationViewPaneClosingEventArgs args)
        {
            UpdateAppTitleMargin(sender);
        }

        private void NavigationViewControl_PaneOpening(NavigationView sender, object args)
        {
            UpdateAppTitleMargin(sender);
        }

        private void NavigationViewControl_DisplayModeChanged(NavigationView sender, NavigationViewDisplayModeChangedEventArgs args)
        {
            Thickness currMargin = AppTitleBar.Margin;

            AppTitleBar.Margin = sender.DisplayMode == NavigationViewDisplayMode.Minimal &&
                         sender.IsBackButtonVisible != NavigationViewBackButtonVisible.Collapsed
                ? new Thickness((sender.CompactPaneLength * 2) - 8, currMargin.Top, currMargin.Right, currMargin.Bottom)
                : new Thickness(sender.CompactPaneLength, currMargin.Top, currMargin.Right, currMargin.Bottom);

            UpdateAppTitleMargin(sender);
            UpdateHeaderMargin(sender);
        }

        private void UpdateAppTitleMargin(NavigationView sender)
        {
            const int smallLeftIndent = 4, largeLeftIndent = 24;

            Thickness currMargin = AppTitle.Margin;

            AppTitle.Margin = (sender.DisplayMode == NavigationViewDisplayMode.Expanded && sender.IsPaneOpen) ||
                     (sender.DisplayMode == NavigationViewDisplayMode.Compact && sender.IsPaneOpen) ||
                     sender.DisplayMode == NavigationViewDisplayMode.Minimal
                ? new Thickness(smallLeftIndent, currMargin.Top, currMargin.Right, currMargin.Bottom)
                : new Thickness(largeLeftIndent, currMargin.Top, currMargin.Right, currMargin.Bottom);
        }

        private void UpdateHeaderMargin(NavigationView sender)
        {
            if (PageHeader != null)
            {
                PageHeader.HeaderPadding = sender.DisplayMode == NavigationViewDisplayMode.Minimal
                    ? (Thickness)Application.Current.Resources["PageHeaderMinimalPadding"]
                    : (Thickness)Application.Current.Resources["PageHeaderDefaultPadding"];

                Thickness currMargin = PageHeader.Margin;

                PageHeader.Margin = sender.DisplayMode == NavigationViewDisplayMode.Minimal &&
                         sender.IsBackButtonVisible != NavigationViewBackButtonVisible.Collapsed
                    ? new Thickness(-sender.CompactPaneLength + 8, currMargin.Top, currMargin.Right, currMargin.Bottom)
                    : new Thickness(0, currMargin.Top, currMargin.Right, currMargin.Bottom);
            }
        }

        #region 状态栏
        public enum MessageColor
        {
            Red,
            Blue,
            Green,
            Yellow,
        }

        public void ShowProgressRing()
        {
            if (PageHeader != null)
            {
                PageHeader.ProgressRing.Visibility = Visibility.Visible;
                PageHeader.ProgressRing.IsActive = true;
            }
        }

        public void HideProgressRing()
        {
            if (PageHeader != null)
            {
                PageHeader.ProgressRing.IsActive = false;
                PageHeader.ProgressRing.Visibility = Visibility.Collapsed;
            }
        }

        public void ShowProgressBar()
        {
            ProgressBar.Visibility = Visibility.Visible;
            ProgressBar.IsIndeterminate = true;
            ProgressBar.ShowError = false;
            ProgressBar.ShowPaused = false;
        }

        public void PausedProgressBar()
        {
            ProgressBar.Visibility = Visibility.Visible;
            ProgressBar.IsIndeterminate = true;
            ProgressBar.ShowError = false;
            ProgressBar.ShowPaused = true;
        }

        public void ErrorProgressBar()
        {
            ProgressBar.Visibility = Visibility.Visible;
            ProgressBar.IsIndeterminate = true;
            ProgressBar.ShowPaused = false;
            ProgressBar.ShowError = true;
        }

        public void HideProgressBar()
        {
            ProgressBar.Visibility = Visibility.Collapsed;
            ProgressBar.IsIndeterminate = false;
            ProgressBar.ShowError = false;
            ProgressBar.ShowPaused = false;
        }

        public void ShowMessage(string message, string info, MessageColor color)
        {
            if (PageHeader != null)
            {
                PageHeader.Message.Text = message;
                PageHeader.MessageInfo.Glyph = info;
                PageHeader.MessageInfo.Foreground = color switch
                {
                    MessageColor.Red => new SolidColorBrush(Color.FromArgb(255, 245, 88, 98)),
                    MessageColor.Blue => new SolidColorBrush(Color.FromArgb(255, 119, 220, 255)),
                    MessageColor.Green => new SolidColorBrush(Color.FromArgb(255, 155, 230, 155)),
                    MessageColor.Yellow => new SolidColorBrush(Color.FromArgb(255, 254, 228, 160)),
                    _ => new SolidColorBrush(Colors.Yellow),
                };
                PageHeader?.RectanglePointerEntered();
            }
        }

        public void HideMessage()
        {
            PageHeader?.RectanglePointerExited();
        }

        #endregion
    }
}

'WSA-Tools/WSATools/WSATools/Helpers/UIHelper.cs'
:﻿using ModernWpf.Media.Animation;
using System;
using System.Collections.ObjectModel;
using System.Drawing;
using System.Threading.Tasks;
using WSATools.Pages;

namespace WSATools.Helpers
{
    internal static class UIHelper
    {
        public const string Error = "";
        public const string Seccess = "";
        public const string Message = "";
        public const string Warnning = "";
        public const string AppTitle = "Universal-like Minecraft Launcher";

        public static float DpiX, DpiY;
        public static MainPage MainPage;
        public static MainWindow MainWindow;
        public static bool IsShowingProgressRing, IsShowingProgressBar, IsShowingMessage;
        private static readonly ObservableCollection<(string message, string info, MainPage.MessageColor color)> MessageList = new();

        public enum NavigationThemeTransition
        {
            Default,
            Entrance,
            DrillIn,
            Suppress
        }

        static UIHelper()
        {
            Graphics graphics = Graphics.FromHwnd(IntPtr.Zero);
            DpiX = graphics.DpiX / 96;
            DpiY = graphics.DpiY / 96;
        }

        public static void Navigate(Type pageType, object e = null, NavigationThemeTransition Type = NavigationThemeTransition.Default)
        {
            _ = Type switch
            {
                NavigationThemeTransition.DrillIn => MainPage?.NavigationViewFrame.Navigate(pageType, e, new DrillInNavigationTransitionInfo()),
                NavigationThemeTransition.Entrance => MainPage?.NavigationViewFrame.Navigate(pageType, e, new EntranceNavigationTransitionInfo()),
                NavigationThemeTransition.Suppress => MainPage?.NavigationViewFrame.Navigate(pageType, e, new SuppressNavigationTransitionInfo()),
                NavigationThemeTransition.Default => MainPage?.NavigationViewFrame.Navigate(pageType, e),
                _ => MainPage?.NavigationViewFrame.Navigate(pageType, e),
            };
        }

        /// <summary>
        /// 显示进度环
        /// </summary>
        public static void ShowProgressRing()
        {
            IsShowingProgressRing = true;
            MainPage.ShowProgressRing();
        }

        /// <summary>
        /// 隐藏进度环
        /// </summary>
        public static void HideProgressRing()
        {
            IsShowingProgressRing = false;
            MainPage.HideProgressRing();
        }

        /// <summary>
        /// 显示进度条-正常
        /// </summary>
        public static void ShowProgressBar()
        {
            IsShowingProgressBar = true;
            MainPage.ShowProgressBar();
        }

        /// <summary>
        /// 显示进度条-暂停
        /// </summary>
        public static void PausedProgressBar()
        {
            IsShowingProgressBar = true;
            MainPage.PausedProgressBar();
        }

        /// <summary>
        /// 显示进度条-错误
        /// </summary>
        public static void ErrorProgressBar()
        {
            IsShowingProgressBar = true;
            MainPage.ErrorProgressBar();
        }

        /// <summary>
        /// 隐藏进度条
        /// </summary>
        public static void HideProgressBar()
        {
            IsShowingProgressBar = false;
            MainPage.HideProgressBar();
        }

        /// <summary>
        /// 展示应用内通知
        /// </summary>
        /// <param name="message">要展示的消息</param>
        /// <param name="info">消息前的图标</param>
        /// <param name="color">消息前图标的颜色</param>
        public static async void ShowMessage(string message, string info = Message, MainPage.MessageColor color = MainPage.MessageColor.Blue)
        {
            MessageList.Add((message, info, color));
            if (!IsShowingMessage)
            {
                IsShowingMessage = true;
                while (MessageList.Count > 0)
                {
                    if (!string.IsNullOrEmpty(MessageList[0].message))
                    {
                        string messages = $"{MessageList[0].message.Replace("\n", " ")}";
                        MainPage.ShowMessage(messages, MessageList[0].info, MessageList[0].color);
                        await Task.Delay(3000);
                    }
                    MessageList.RemoveAt(0);
                    if (MessageList.Count == 0)
                    {
                        MainPage.HideMessage();
                    }
                }
                IsShowingMessage = false;
            }
        }

        /// <summary>
        /// 获取时间内的问候语
        /// </summary>
        /// <returns>问候语</returns>
        public static string GetGreetings()
        {
            string str = "";
            DateTime now = DateTime.Now;
            int times = now.Hour;
            if (times is >= 0 and < 6) { str = "熬夜对身体不好哦"; }
            if (times is >= 6 and < 9) { str = "早安"; }
            if (times is >= 9 and < 11) { str = "上午好"; }
            if (times is >= 11 and < 13) { str = "中午好"; }
            if (times is >= 13 and < 17) { str = "下午好"; }
            if (times is >= 17 and < 19) { str = "吃过晚饭了吗"; }
            if (times is >= 19 and < 24) { str = "晚安"; }
            return str;
        }

        /// <summary>
        /// 将字节数转换为可读数据
        /// </summary>
        /// <param name="size">字节数</param>
        /// <returns>xx.xx xB</returns>
        public static string GetSizeString(this double size)
        {
            int index = 0;
            while (true)
            {
                index++;
                size /= 1024;
                if (size is > 0.7 and < 716.8) { break; }
                else if (size >= 716.8) { continue; }
                else if (size <= 0.7)
                {
                    size *= 1024;
                    index--;
                    break;
                }
            }
            string str = string.Empty;
            switch (index)
            {
                case 0: str = "B"; break;
                case 1: str = "KB"; break;
                case 2: str = "MB"; break;
                case 3: str = "GB"; break;
                case 4: str = "TB"; break;
                default:
                    break;
            }
            return $"{size:N2}{str}";
        }
    }
}

