public class Spring : AnimationCurve
{
    public int Tension { get; set; } = 40;
    public int Friction { get; set; } = 7;

    public IEnumerable<double> Steps(int stepsPerSecond)
    {
        //Port of http://facebook.github.io/rebound/
        const double restVelocityThreshold = .001, distanceFromRestThreshold = .001, startValue = 0, endValue = 1.0;
        double stepTime = 1.0 / stepsPerSecond, halfStep = stepTime / 2.0;
        double tension = (Tension - 30.0) * 3.62 + 194.0, friction = (Friction - 8.0) * 3.0 + 25.0;
        double position = startValue, velocity = 0, seedPosition = 0;
        yield return startValue;
        do
        {
            var aVel = velocity;
            var aAcc = tension * (endValue - seedPosition) - friction * velocity;
            double bVel = velocity + aAcc * halfStep, bAcc = tension * (endValue - (position + aVel * halfStep)) - friction * bVel;
            double cVel = velocity + bAcc * halfStep, cAcc = tension * (endValue - (position + bVel * halfStep)) - friction * cVel;
            seedPosition = position + cVel * stepTime;
            double dVel = velocity + cAcc * stepTime, dAcc = tension * (endValue - seedPosition) - friction * dVel;
            double dxdt = 1.0 / 6.0 * (aVel + 2.0 * (bVel + cVel) + dVel), dvdt = 1.0 / 6.0 * (aAcc + 2.0 * (bAcc + cAcc) + dAcc);
            position += dxdt * stepTime;
            velocity += dvdt * stepTime;
            yield return position;
        } while (!(Math.Abs(velocity) < restVelocityThreshold) || (!(Math.Abs(endValue - position) <= distanceFromRestThreshold) && Math.Abs(tension) > .00001));
        yield return endValue;
    }
}

