:﻿using System.Collections.Generic;

namespace AudioSynthesis.Synthesis
{
    internal class VoiceManager
    {
        public class VoiceNode
        {
            public Voice Value;
            public VoiceNode Next;
        }
        //--Variables
        public VoiceStealEnum stealingMethod;
        public int polyphony;
        public LinkedList<Voice> freeVoices;
        public LinkedList<Voice> activeVoices;
        public VoiceNode[,] registry;
        private Voice[] voicePool;
        private Stack<VoiceNode> vnodes;

        //--Public Methods
        public VoiceManager(int voiceCount)
        {
            stealingMethod = VoiceStealEnum.Quietest;
            polyphony = voiceCount;
            //initialize voice containers
            voicePool = new Voice[voiceCount];
            VoiceNode[] nodes = new VoiceNode[voiceCount];
            for (int x = 0; x < voicePool.Length; x++)
            {
                voicePool[x] = new Voice();
                nodes[x] = new VoiceNode();
            }
            vnodes = new Stack<VoiceNode>(nodes);
            //free voice list
            freeVoices = new LinkedList<Voice>(voicePool);
            activeVoices = new LinkedList<Voice>();
            registry = new VoiceNode[Synthesizer.DefaultChannelCount, Synthesizer.DefaultKeyCount];
        }
        public Voice GetFreeVoice()
        {
            if (freeVoices.Count > 0)
            {
                Voice voice = freeVoices.First.Value;
                freeVoices.RemoveFirst();
                return voice;
            }
            switch (stealingMethod)
            {
                case VoiceStealEnum.Oldest:
                    return StealOldest();
                case VoiceStealEnum.Quietest:
                    return StealQuietestVoice();
                default:
                    return null;
            }
        }
        public void AddToRegistry(Voice voice)
        {
            VoiceNode node = vnodes.Pop();
            node.Value = voice;
            node.Next = registry[voice.VoiceParams.channel, voice.VoiceParams.note];
            registry[voice.VoiceParams.channel, voice.VoiceParams.note] = node;
        }
        public void RemoveFromRegistry(int channel, int note)
        {
            VoiceNode node = registry[channel, note];
            while (node != null)
            {
                vnodes.Push(node);
                node = node.Next;
            }
            registry[channel, note] = null;
        }
        public void RemoveFromRegistry(Voice voice)
        {
            VoiceNode node = registry[voice.VoiceParams.channel, voice.VoiceParams.note];
            if (node == null)
                return;
            if (node.Value == voice)
            {
                registry[voice.VoiceParams.channel, voice.VoiceParams.note] = node.Next;
                vnodes.Push(node);
                return;
            }
            else
            {
                VoiceNode node2 = node;
                node = node.Next;
                while (node != null)
                {
                    if (node.Value == voice)
                    {
                        node2.Next = node.Next;
                        vnodes.Push(node);
                        return;
                    }
                    node2 = node;
                    node = node.Next;
                }
            }
        }
        public void ClearRegistry()
        {
            LinkedListNode<Voice> node = activeVoices.First;
            while (node != null)
            {
                VoiceNode vnode = registry[node.Value.VoiceParams.channel, node.Value.VoiceParams.note];
                while (vnode != null)
                {
                    vnodes.Push(vnode);
                    vnode = vnode.Next;
                }
                registry[node.Value.VoiceParams.channel, node.Value.VoiceParams.note] = null;
                node = node.Next;
            }
        }
        public void UnloadPatches()
        {
            for (int x = 0; x < voicePool.Length; x++)
            {
                voicePool[x].Configure(0, 0, 0, null, null);
                foreach (VoiceNode node in vnodes)
                    node.Value = null;
            }
        }

        private Voice StealOldest()
        {
            LinkedListNode<Voice> node = activeVoices.First;
            //first look for a voice that is not playing
            while (node != null && node.Value.VoiceParams.state == VoiceStateEnum.Playing)
                node = node.Next; 
            //if no stopping voice is found use the oldest
            if (node == null) 
                node = activeVoices.First;
            //check and remove from registry
            RemoveFromRegistry(node.Value);
            activeVoices.Remove(node);
            //stop voice if it is not already
            node.Value.VoiceParams.state = VoiceStateEnum.Stopped;
            return node.Value;
        }
        private Voice StealQuietestVoice()
        {
            float voice_volume = 1000f;
            LinkedListNode<Voice> quietest = null;
            LinkedListNode<Voice> node = activeVoices.First;
            while (node != null)
            {
                if (node.Value.VoiceParams.state != VoiceStateEnum.Playing)
                {
                    float volume = node.Value.VoiceParams.CombinedVolume;
                    if (volume < voice_volume)
                    {
                        quietest = node;
                        voice_volume = volume;
                    }
                }
                node = node.Next;
            }
            if (quietest == null)
                quietest = activeVoices.First;
            //check and remove from registry
            RemoveFromRegistry(quietest.Value);
            activeVoices.Remove(quietest);
            //stop voice if it is not already
            quietest.Value.VoiceParams.state = VoiceStateEnum.Stopped;
            return quietest.Value;
        }
        private Voice StealLowestScore()
        {
            LinkedListNode<Voice> node = activeVoices.First;
            LinkedListNode<Voice> lowest = null;
            int lowScore = int.MaxValue;
            while(node != null)
            {
                int score = 0;
                if (node.Value.VoiceParams.state == VoiceStateEnum.Stopped)
                {
                    lowest = node;
                    break;
                }
                else if (node.Value.VoiceParams.state == VoiceStateEnum.Stopping)
                    score -= 50;
                if (node.Value.VoiceParams.channel == Midi.MidiHelper.DrumChannel)
                    score -= 20;

                if (score < lowScore)
                { 
                    lowScore = score;
                    lowest = node;
                }
                node = node.Next;
            }
            //check and remove from registry
            RemoveFromRegistry(lowest.Value);
            activeVoices.Remove(lowest);
            //stop voice if it is not already
            lowest.Value.VoiceParams.state = VoiceStateEnum.Stopped;
            return lowest.Value;
        }
    }
}

'unity-midi/Assets/UnityMidi/CSharpSynth/Source/AudioSynthesis/Sequencer/MidiFileSequencer.cs'
:﻿/*
 *    ______   __ __     _____             __  __  
 *   / ____/__/ // /_   / ___/__  ______  / /_/ /_ 
 *  / /    /_  _  __/   \__ \/ / / / __ \/ __/ __ \
 * / /___ /_  _  __/   ___/ / /_/ / / / / /_/ / / /
 * \____/  /_//_/     /____/\__, /_/ /_/\__/_/ /_/ 
 *                         /____/                  
 * Midi File Sequencer 
 *  Used for situations where the whole midi is available in file format locally or over a network stream.
 *  Loads the midi and calculates the timing before hand so when sequencing no BPM calculation is needed.
 */
using System;
using AudioSynthesis.Midi;
using AudioSynthesis.Synthesis;
using AudioSynthesis.Midi.Event;

namespace AudioSynthesis.Sequencer
{
    public class MidiFileSequencer
    {
        //--Variables
        private Synthesizer synth;
        private MidiMessage[] mdata;
        private bool[] blockList;
        private bool playing = false;
        private double playbackrate = 1.0; // 1/8 to 8
        private int totalTime;
        private int sampleTime;
        private int eventIndex;

        //--Public Properties
        public Synthesizer Synth
        {
            get { return synth; }
            set { synth = value; }
        }
        public bool IsPlaying
        {
            get { return playing; }
        }
        public bool IsMidiLoaded
        {
            get { return mdata != null; }
        }
        public int CurrentTime
        {
            get { return sampleTime; }
        }
        public int EndTime
        {
            get { return totalTime; }
        }
        public double PlaySpeed
        {
            get { return playbackrate; }
            set { playbackrate = SynthHelper.Clamp(value, .125, 8.0); }
        }

        //--Public Methods
        public MidiFileSequencer(Synthesizer synth)
        {
            this.synth = synth;
            blockList = new bool[Synthesizer.DefaultChannelCount];
        }
        public bool LoadMidi(IResource midiFile)
        {
            if (playing == true)
                return false;
            LoadMidiFile(new MidiFile(midiFile));
            return true;
        }
        public bool LoadMidi(MidiFile midiFile)
        {
            if (playing == true)
                return false;
            LoadMidiFile(midiFile);
            return true;
        }
        public bool UnloadMidi()
        {
            if (playing == true)
                return false;
            mdata = null;
            return true;
        }
        public void Play()
        {
            if (playing == true || mdata == null)
                return;
            playing = true;
        }
        public void Stop()
        {
            playing = false;
            sampleTime = 0;
            eventIndex = 0;
        }
        public bool IsChannelMuted(int channel)
        {
            return blockList[channel];
        }
        public void MuteAllChannels()
        {
            for (int x = 0; x < blockList.Length; x++)
                blockList[x] = true;
        }
        public void UnMuteAllChannels()
        {
            Array.Clear(blockList, 0, blockList.Length);
        }
        public void SetMute(int channel, bool muteValue)
        {
            blockList[channel] = muteValue;
        }
        public void Seek(TimeSpan time)
        {
            int targetSampleTime = (int)(synth.SampleRate * time.TotalSeconds);
            if (targetSampleTime > sampleTime)
            {//process forward
                SilentProcess(targetSampleTime - sampleTime);
            }
            else if (targetSampleTime < sampleTime)
            {//we have to restart the midi to make sure we get the right state: instruments, volume, pan, etc
                sampleTime = 0;
                eventIndex = 0;
                synth.NoteOffAll(true);
                synth.ResetPrograms();
                synth.ResetSynthControls();
                SilentProcess(targetSampleTime);
            }
        }
        public void FillMidiEventQueue()
        {
            if (!playing || synth.midiEventQueue.Count != 0)
                return;
            if (sampleTime >= totalTime)
            {
                sampleTime = 0;
                eventIndex = 0;
                playing = false;
                synth.NoteOffAll(true);
                synth.ResetPrograms();
                synth.ResetSynthControls();
                return;
            }
            int newMSize = (int)(synth.MicroBufferSize * playbackrate);       
            for (int x = 0; x < synth.midiEventCounts.Length; x++)
            {
                sampleTime += newMSize;
                while (eventIndex < mdata.Length && mdata[eventIndex].delta < sampleTime)
                {
                    if (mdata[eventIndex].command != 0x90 || blockList[mdata[eventIndex].channel] == false)
                    {
                        synth.midiEventQueue.Enqueue(mdata[eventIndex]);
                        synth.midiEventCounts[x]++;
                    }
                    eventIndex++;
                }
            }
        }
        //--Private Methods
        private void LoadMidiFile(MidiFile midiFile)
        {
            //Converts midi to sample based format for easy sequencing
            double BPM = 120.0;
            //Combine all tracks into 1 track that is organized from lowest to highest absolute time
            if(midiFile.Tracks.Length > 1 || midiFile.Tracks[0].EndTime == 0)
                midiFile.CombineTracks();
            mdata = new MidiMessage[midiFile.Tracks[0].MidiEvents.Length];
            //Convert delta time to sample time
            eventIndex = 0;
            sampleTime = 0;
            //Calculate sample based time using double counter and round down to nearest integer sample.
            double absDelta = 0.0;
            for (int x = 0; x < mdata.Length; x++)
            {
                MidiEvent mEvent = midiFile.Tracks[0].MidiEvents[x];
                mdata[x] = new MidiMessage((byte)mEvent.Channel, (byte)mEvent.Command, (byte)mEvent.Data1, (byte)mEvent.Data2);
                absDelta += synth.SampleRate * mEvent.DeltaTime * (60.0 / (BPM * midiFile.Division));
                mdata[x].delta = (int)absDelta;
                //Update tempo
                if (mEvent.Command == 0xFF && mEvent.Data1 == 0x51)
                    BPM = Math.Round(MidiHelper.MicroSecondsPerMinute / (double)((MetaNumberEvent)mEvent).Value, 2);
            }
            //Set total time to proper value
            totalTime = mdata[mdata.Length - 1].delta;
        }
        private void SilentProcess(int amount)
        {
            while (eventIndex < mdata.Length && mdata[eventIndex].delta < (sampleTime + amount))
            {
                if (mdata[eventIndex].command != 0x90)
                {
                    MidiMessage m = mdata[eventIndex]; 
                    synth.ProcessMidiMessage(m.channel, m.command, m.data1, m.data2);
                }
                eventIndex++;
            }
            sampleTime += amount;
        }
    }
}

