{
	bFound = false;
	TSharedPtr<FJsonObject> CurrentObject = Parser ? Parser->GetJsonRoot() : nullptr;
	if (!CurrentObject)
	{
		return "";
	}

	TSharedPtr<FJsonValue> JsonValue = FglTFRuntimeParser::GetJSONObjectFromRelativePath(CurrentObject.ToSharedRef(), Path);
