    std::atomic_bool m_ready{false};
    std::atomic_bool m_error{false};

    enum LockID {
        NOLOCK = 0,
        SETPLUGINSCREENUPDATECALLBACK,
        SETONCONNECTCALLBACK,
        SETONCLOSECALLBACK,
        INIT1,
        INIT2,
        CLOSE,
        ADDPLUGIN,
        DELPLUGIN,
        EDITPLUGIN,
        HIDEPLUGIN,
        GETPLUGINSETTINGS,
        SETPLUGINSETTINGS,
        BYPASSPLUGIN,
        UNBYPASSPLUGIN,
        EXCHANGEPLUGINS,
        GETRECENTS,
        SETPRESET,
        GETPARAMETERVALUE,
        SETPARAMETERVALUE,
        GETALLPARAMETERVALUES,
        SENDMOUSEEVENT,
        KEYPRESSED,
        UPDATESCREENCAPTUREAREA,
        RESCAN,
        RESTART,
        UPDATECPULOAD1,
        UPDATECPULOAD2,
        GETLOADEDPLUGINSSTRING,
        UPDATEPLUGINLIST,
        SETMONOCHANNELS
    };

    struct LockByID : public LogTagDelegate {
        Client& client;
        LockID lockid;
        bool locked = false;

        LockByID(Client& c, LockID id, bool enforce = true) : client(c), lockid(id) {
            setLogTagSource(&client);
            traceScope();
            traceln("id=" << (int)id << " enforce=" << (int)enforce);
            if (enforce) {
                lock();
                locked = true;
                traceln("locked");
            } else {
                if (tryLock()) {
                    locked = true;
                    traceln("locked");
                } else {
                    traceln("lock failed, lock aquired by id " << client.m_clientMtxId);
                }
            }
        }

        ~LockByID() {
            traceScope();
            if (locked) {
                unlock();
                traceln("unlocked id " << lockid);
            }
        }

        inline void lock() {
            client.m_clientMtx.lock();
            client.m_clientMtxId = lockid;
        }

        inline bool tryLock() {
            if (client.m_clientMtx.try_lock()) {
                client.m_clientMtxId = lockid;
                return true;
            }
            return false;
        }

        inline void unlock() {
            client.m_clientMtxId = NOLOCK;
            client.m_clientMtx.unlock();
        }
    };

    std::mutex m_clientMtx;
    LockID m_clientMtxId = NOLOCK;

