#define FATAL_IMPL_BENCHMARK(Class, Group, Name, UserLoop, Iterations) \
  class Class { \
    using timer = ::fatal::benchmark::detail::registry::timer; \
    \
    ::fatal::benchmark::controller<timer> benchmark; \
    \
  public: \
