    } else {
      sequential_ifs_impl<Strings...>::match(
        std::forward<Input>(input),
        count
      );
    }
  }
};

struct visitor {
  template <typename String>
  void operator ()(
    tag<String>,
    std::string const &s,
    unsigned &count
  ) {
    count += s.size();
  }
};

template <typename... Strings>
struct benchmark_impl {
