:﻿using System.Collections.Specialized;
using System.Linq;
using System.Text;
using StackExchange.Exceptional.Internal;
using System;
using System.Collections.Generic;

namespace StackExchange.Exceptional.Pages
{
    /// <summary>
    /// An error detail page for showing the specifics on a single error.
    /// </summary>
    public class ErrorDetailPage : WebPage
    {
        private readonly Guid _guid;

        /// <summary>
        /// Whether to show the action links for this exception.
        /// </summary>
        public bool ShowActionLinks { get; set; }

        /// <summary>
        /// Creates an <see cref="ErrorDetailPage"/>.
        /// </summary>
        /// <param name="error">The error we're rendering details.</param>
        /// <param name="settings">Current Exceptional settings.</param>
        /// <param name="store">The store this error is from.</param>
        /// <param name="baseURL">The base URL for the current request.</param>
        /// <param name="guid">The id for the error (populate even if the error is null).</param>
        public ErrorDetailPage(Error error, ExceptionalSettingsBase settings, ErrorStore store, string baseURL, Guid guid)
            : base(error, settings, store, baseURL, "Error - " + (error?.Message ?? "Not Found"))
        {
            _guid = guid;
        }

        /// <summary>
        /// Renders the main contents of the page.
        /// </summary>
        /// <param name="sb">The <see cref="StringBuilder"/> to render to.</param>
        protected override void RenderInnerHtml(StringBuilder sb)
        {
            void RenderVariableTable(string title, string className, NameValueCollection vars, bool renderUrls = false)
            {
                if (vars == null || vars.Count == 0) return;

                var fetchError = vars[Constants.CollectionErrorKey];
                var errored = fetchError.HasValue();
                var keys = vars.AllKeys.Where(key => !HiddenHttpKeys.Contains(key) && key != Constants.CollectionErrorKey).OrderBy(k => k);

                sb.AppendFormat("  <div class=\"{0}\">", className).AppendLine();
                if (errored)
                {
                    sb.AppendFormat("    <h3 class=\"title-error\">{0} - Error while gathering data</h3>", title).AppendLine();
                }
                else
                {
                    sb.AppendFormat("    <h3>{0}</h3>", title).AppendLine();
                }
                if (keys.Any())
                {
                    var hiddenRows = new StringBuilder();
                    sb.AppendLine("    <div class=\"side-scroll\">")
                      .AppendLine("      <table class=\"alt-rows key-value\">")
                      .AppendLine("        <tbody>");
                    foreach (var k in keys)
                    {
                        // If this has no value, skip it
                        if (vars[k].HasValue())
                        {
                            // If this is a hidden row, buffer it up, since CSS has no clean mechanism for :visible:nth-row(odd) type styling behavior
                            (DefaultHttpKeys.Contains(k) ? hiddenRows : sb).AppendFormat("        <tr><td>{0}</td><td>{1}</td></tr>", k.HtmlEncode(), Linkify(vars[k])).AppendLine();
                        }
                    }
                    if (renderUrls && vars["Request Method"].IsNullOrEmpty()) // told to render and we don't have them elsewhere
                    {
                        var method = Error.HTTPMethod;
                        if (method.HasValue())
                        {
                            sb.AppendFormat("        <tr><td>Method</td><td>{0}</td></tr>", method).AppendLine();
                            var fullUrl = Error.GetFullUrl();
                            if (fullUrl.HasValue())
                            {
                                sb.AppendFormat("        <tr><td>URL and Query</td><td>{0}</td></tr>", method == "GET" ? Linkify(fullUrl) : fullUrl.HtmlEncode()).AppendLine();
                            }
                        }
                    }
                    sb.AppendLine("        </tbody>");
                    if (hiddenRows.Length > 0)
                    {
                        sb.AppendLine("        <tbody class=\"hidden\">")
                          .Append(hiddenRows)
                          .AppendLine("        </tbody>");
                    }
                    sb.AppendLine("      </table>")
                      .AppendLine("    </div>");
                }
                if (errored)
                {
                    sb.AppendFormat("<span class=\"custom-error-label\">Get {0} threw an exception:</span>", title)
                      .AppendFormat("<pre class=\"stack\"><code>{0}</code></pre>", fetchError.HtmlEncode());
                }
                sb.AppendFormat("  </div>");
            }

            void RenderKeyValueTable(IEnumerable<KeyValuePair<string, string>> kvPairs)
            {
                if (kvPairs?.Any() == true)
                {
                    sb.AppendLine("    <div class=\"side-scroll\">")
                      .AppendLine("      <table class=\"alt-rows key-value\">");
                    foreach (var kv in kvPairs)
                    {
                        sb.Append("        <tr>")
                          .Append("<td>").AppendHtmlEncode(kv.Key).Append("</td>")
                          .Append("<td>").Append(Linkify(kv.Value)).Append("</td>")
                          .AppendLine("</tr>");
                    }
                    sb.AppendLine("      </table>")
                      .AppendLine("    </div>");
                }
            }

            if (Error == null)
            {
                sb.AppendFormat("  <h1 class=\"not-found\">Oh no! Error {0} was not found!</h1>", _guid.ToString()).AppendLine();
            }
            else
            {
                sb.Append("  <h1>").AppendHtmlEncode(Error.Message).AppendLine("</h1>")
                  .Append("  <div class=\"subtitle\">").AppendHtmlEncode(Error.Type);
                if (Error.DuplicateCount > 1)
                {
                    sb.Append(" <span class=\"duplicate-count\">(thrown ").Append(Error.DuplicateCount.Value).AppendLine(" times)</span>");
                }
                sb.AppendLine("</div>")
                  .Append("  <pre class=\"stack dark\"><code class=\"nohighlight\">").AppendLine(ExceptionalUtils.StackTrace.HtmlPrettify(Error.Detail, Settings.StackTrace)).AppendLine("</code></pre>")
                  // TODO: Controls for show/hide of async .stack.row.async in the block above
                  // TODO: Remove - temporarily showing the raw while the user-friendlier display above gets tuned
                  //.Append("  <pre class=\"stack\"><code>").AppendHtmlEncode(Error.Detail).AppendLine().AppendLine("</code></pre>")
                  .Append("  <p class=\"sub-info\">occurred <b title=\"")
                  .AppendHtmlEncode(Error.CreationDate.ToLongDateString()).Append(" at ").AppendHtmlEncode(Error.CreationDate.ToLongTimeString())
                  .Append("\">")
                  .Append(Error.CreationDate.ToRelativeTime())
                  .Append("</b> on ")
                  .AppendHtmlEncode(Error.MachineName);
                if (ShowActionLinks)
                {
                    sb.Append(" <span>(<a href=\"delete?guid=").Append(Error.GUID.ToString()).AppendLine("\">delete</a>)</span>");
                }
                sb.Append("</p>");
                if (Error.Commands != null)
                {
                    foreach (var cmd in Error.Commands)
                    {
                        var lang = cmd.GetHighlightLanguage();
                        sb.Append("  <h3>Command: ").AppendHtmlEncode(cmd.Type).AppendLine("</h3>")
                          .Append("  <pre class=\"command\"><code");
                        if (lang.HasValue())
                        {
                            sb.Append(" class=\"").Append(lang).Append("\"");
                        }
                        sb.Append(">")
                          .AppendHtmlEncode(cmd.CommandString)
                          .AppendLine("</code></pre>");

                        RenderKeyValueTable(cmd.Data);
                    }
                }
                RenderVariableTable("Server Variables", "server-variables", Error.ServerVariables, renderUrls: true);

                if (Error.CustomData?.Count > 0)
                {
                    var errored = Error.CustomData.ContainsKey(Constants.CustomDataErrorKey);
                    var cdKVs = Error.CustomData.Where(kv => kv.Key != Constants.CustomDataErrorKey);
                    sb.AppendLine("  <div class=\"custom-data\">");
                    if (errored)
                    {
                        sb.AppendLine("    <h3 class=\"title-error\">Custom - Error while gathering custom data</h3>");
                    }
                    else
                    {
                        sb.AppendLine("    <h3>Custom</h3>");
                    }
                    if (cdKVs.Any())
                    {
                        RenderKeyValueTable(cdKVs);
                    }
                    if (errored)
                    {
                        sb.AppendLine("    <span class=\"custom-error-label\">GetCustomData threw an exception:</span>")
                          .AppendLine("    <pre class=\"stack\"><code>").Append(Error.CustomData[Constants.CustomDataErrorKey]).AppendLine("</code></pre>");
                    }
                    sb.AppendLine("  </div>");
                }
                RenderVariableTable("Querystring", "querystring", Error.QueryString);
                RenderVariableTable("Form", "form", Error.Form);
                RenderVariableTable("Cookies", "cookies", Error.Cookies);
                RenderVariableTable("Request Headers", "headers", Error.RequestHeaders);
            }
        }
    }
}

'StackExchange.Exceptional/src/StackExchange.Exceptional.AspNetCore/ExceptionalMiddleware.cs'
:﻿using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Http.Features;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Newtonsoft.Json;
using StackExchange.Exceptional.Internal;
using StackExchange.Exceptional.Pages;
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

namespace StackExchange.Exceptional
{
    /// <summary>
    /// HTTP module that catches and log exceptions from ASP.NET Applications.
    /// </summary>
    public class ExceptionalMiddleware
    {
        private readonly RequestDelegate _next;
        private readonly ILogger _logger;
#if NETSTANDARD2_0 || NET461
        private readonly IHostingEnvironment _env;
#else
        private readonly IWebHostEnvironment _env;
#endif
        private readonly IOptions<ExceptionalSettings> _settings;

        /// <summary>
        /// Creates a new instance of <see cref="ExceptionalMiddleware"/>
        /// </summary>
        /// <param name="next">The next delegate in the chain to execute.</param>
        /// <param name="settings">The <see cref="ExceptionalSettings"/> wrapper that contains current settings.</param>
        /// <param name="hostingEnvironment">The <see cref="IHostingEnvironment"/> to get pathing data from.</param>
        /// <param name="loggerFactory">The logger factor to record exceptions to.</param>
        public ExceptionalMiddleware(
            RequestDelegate next,
            IOptions<ExceptionalSettings> settings,
#if NETSTANDARD2_0 || NET461
        IHostingEnvironment hostingEnvironment,
#else
        IWebHostEnvironment hostingEnvironment,
#endif
            ILoggerFactory loggerFactory)
        {
            _next = next;
            _env = hostingEnvironment;
            _logger = loggerFactory.CreateLogger<ExceptionalMiddleware>();
            _settings = settings;

            // If an ApplicationName isn't provided, default to IHostingEnvironment.ApplicationName
            if (!_settings.Value.Store.ApplicationName.HasValue())
            {
                _settings.Value.Store.ApplicationName = _env.ApplicationName;
            }
        }

        /// <summary>
        /// Executes the Exceptional-wrapped middleware.
        /// </summary>
        /// <param name="context">The current <see cref="HttpContext"/>.</param>
        public async Task Invoke(HttpContext context)
        {
            try
            {
                await _next.Invoke(context);
            }
            catch (Exception ex)
            {
                _logger.LogError(0, ex, "An unhandled exception has occurred, logging to Exceptional");
                var error = await ex.LogAsync(context).ConfigureAwait(false);

                // If options say to do so, show the exception page to the user
                if (_settings.Value.UseExceptionalPageOnThrow && error != null)
                {
                    var response = context.Response;
                    if (context.Response.HasStarted)
                    {
                        _logger.LogWarning("The response has already started, the Exceptional error page will not be displayed.");
                        throw;
                    }

                    try
                    {
                        response.HttpContext.Features.Get<IHttpResponseFeature>().ReasonPhrase = null;
                        response.Headers.Clear();
                        if (response.Body.CanSeek)
                        {
                            response.Body.SetLength(0);
                        }
                        response.StatusCode = 500;

                        var page = new ErrorDetailPage(error, _settings.Value, _settings.Value.DefaultStore, "", error.GUID)
                        {
                            HeaderTitle = "An error was thrown during this request.",
                            PageTitle = "An error was thrown during this request.",
                            InlineCSS = true,
                            IncludeJS = false,
                            ShowActionLinks = false
                        };
                        response.ContentType = "text/html";
                        await response.WriteAsync(page.Render()).ConfigureAwait(false);

                        return;
                    }
                    catch (Exception pex)
                    {
                        _logger.LogError(0, pex, "An exception was thrown attempting to display the Exceptional page.");
                    }
                }
                throw;
            }
        }

        /// <summary>
        /// Convenience method for handling a request, for usage in your routing, MVC, etc. See example.
        /// </summary>
        /// <example>
        /// <code>
        /// [Route("/path/my-route")]
        /// public async Task Exceptions() => await ExceptionalMiddleware.HandleRequestAsync(HttpContext);
        /// </code>
        /// </example>
        /// <param name="context">The context to process, usually HttpContext from a controller.</param>
        /// <returns>A task to await.</returns>
        public static async Task HandleRequestAsync(HttpContext context)
        {
            async Task Content(string content, string mime = "text/html")
            {
                context.Response.ContentType = mime;
                await context.Response.WriteAsync(content).ConfigureAwait(false);
            }
            Task JsonResult(bool result) => Content(@"{""result"":" + (result ? "true" : "false") + "}", "text/javascript");
            Task Page(WebPage page) => Content(page.Render());
            Task Resource(Resources.ResourceCache cache)
            {
                context.Response.Headers["Cache-Control"] = "private, max-age=86400";
                return Content(cache.Content, cache.MimeType);
            }
            string TrimEnd(string s, string value) => s.EndsWith(value) ? s.Remove(s.LastIndexOf(value, StringComparison.Ordinal)) : s;

            // In MVC requests, PathInfo isn't set - determine via Path..
            // e.g. "/errors/info" or "/errors/"
            var match = Regex.Match(context.Request.Path, @"/?(?<resource>[\w\-\.]+)/?$");
            var resource = match.Success ? match.Groups["resource"].Value.ToLower(CultureInfo.InvariantCulture) : string.Empty;

            IEnumerable<Guid> GetFormGuids()
            {
                try
                {
                    return context.Request.Form["ids"].Select(Guid.Parse) ?? Enumerable.Empty<Guid>();
                }
                catch
                {
                    return Enumerable.Empty<Guid>();
                }
            }

            var settings = context.RequestServices.GetRequiredService<IOptions<ExceptionalSettings>>().Value;
            var store = settings.DefaultStore;
            string errorGuid;

            switch (context.Request.Method)
            {
                case "POST":
                    errorGuid = context.Request.HasFormContentType ? context.Request.Form["guid"].ToString() : string.Empty;
                    switch (resource)
                    {
                        case KnownRoutes.Delete:
                            await JsonResult(await store.DeleteAsync(errorGuid.ToGuid()).ConfigureAwait(false)).ConfigureAwait(false);
                            return;
                        case KnownRoutes.DeleteAll:
                            await JsonResult(await store.DeleteAllAsync().ConfigureAwait(false)).ConfigureAwait(false);
                            return;
                        case KnownRoutes.DeleteList:
                            await JsonResult(await store.DeleteAsync(GetFormGuids()).ConfigureAwait(false)).ConfigureAwait(false);
                            return;
                        case KnownRoutes.Protect:
                            await JsonResult(await store.ProtectAsync(errorGuid.ToGuid()).ConfigureAwait(false)).ConfigureAwait(false);
                            return;
                        case KnownRoutes.ProtectList:
                            await JsonResult(await store.ProtectAsync(GetFormGuids()).ConfigureAwait(false)).ConfigureAwait(false);
                            return;
                        default:
                            await Content("Invalid POST Request").ConfigureAwait(false);
                            return;
                    }
                case "GET":
                    errorGuid = context.Request.Query["guid"].ToString() ?? string.Empty;
                    switch (resource)
                    {
                        case KnownRoutes.Info:
                            var guid = errorGuid.ToGuid();
                            var error = errorGuid.HasValue() ? await store.GetAsync(guid).ConfigureAwait(false) : null;
                            await Page(new ErrorDetailPage(error, settings, store, TrimEnd($"{context.Request.PathBase}{context.Request.Path}", "/info"), guid)).ConfigureAwait(false);
                            return;
                        case KnownRoutes.Json:
                            context.Response.ContentType = "application/json";
                            DateTime? since = long.TryParse(context.Request.Headers["since"], out long sinceLong)
                                     ? new DateTime(1970, 1, 1, 0, 0, 0).AddSeconds(sinceLong)
                                     : (DateTime?)null;

                            var errors = await store.GetAllAsync().ConfigureAwait(false);
                            if (since.HasValue)
                            {
                                errors = errors.Where(e => e.CreationDate >= since).ToList();
                            }
                            await context.Response.WriteAsync(JsonConvert.SerializeObject(errors)).ConfigureAwait(false);
                            return;
                        case KnownRoutes.Css:
                            await Resource(Resources.BundleCss).ConfigureAwait(false);
                            return;
                        case KnownRoutes.Js:
                            await Resource(Resources.BundleJs).ConfigureAwait(false);
                            return;
                        case KnownRoutes.Test:
                            throw new Exception("This is a test. Please disregard. If this were a real emergency, it'd have a different message.");
                        default:
                            context.Response.Headers["Cache-Control"] = "no-cache, no-store";
                            await Page(new ErrorListPage(store, settings, $"{context.Request.PathBase}{context.Request.Path}", await store.GetAllAsync().ConfigureAwait(false))).ConfigureAwait(false);
                            return;
                    }
                default:
                    await Content("Unsupported request method: " + context.Request.Method).ConfigureAwait(false);
                    return;
            }
        }
    }
}

