private Dictionary<ProjectGraphNode, IEnumerable<PackageChange>> FindChangedNugetPackages(
    AffectedProcessorContext context)
{
    var changes = new Dictionary<ProjectGraphNode, IEnumerable<PackageChange>>();
    var changedPackageFiles = context.ChangedFiles
        .Where(f => f.EndsWith("Directory.Packages.props"))
        .OrderBy(p => p.Length)
        .Select(p => new FileInfo(p))
        .ToList();

    if (!changedPackageFiles.Any())
        return changes;

    if (context.RepositoryPath == changedPackageFiles[0]
            .DirectoryName)
        changedPackageFiles = new List<FileInfo>
        {
            changedPackageFiles[0]
        };

    for (var i = 1; i < changedPackageFiles.Count; i++)
    {
        for (var q = 0; q < i; q++)
        {
            if (changedPackageFiles[i]
                .FullName.StartsWith(changedPackageFiles[q]
                    .DirectoryName!))
            {
                changedPackageFiles.RemoveAt(i);
                i -= 1;
                break;
            }
        }
    }

    var relatedProjects = context.Graph.ProjectNodes
        .Where(node =>
            changedPackageFiles.Any(f => node.ProjectInstance.FullPath.StartsWith(f.DirectoryName!)));

    foreach (var graphNode in relatedProjects)
    {
        var fromFile = context.ChangesProvider.LoadProject(context.RepositoryPath,
            graphNode.ProjectInstance.FullPath, context.FromRef, false);
        var toFile = context.ChangesProvider.LoadProject(context.RepositoryPath,
            graphNode.ProjectInstance.FullPath, context.ToRef, true);

        // Parse props files into package and version dictionary
        var fromPackages = NugetHelper.ParseDirectoryPackageProps(fromFile);
        var toPackages = NugetHelper.ParseDirectoryPackageProps(toFile);

        // Compare both dictionaries
        if (NugetHelper.TryFindDiffPackageDictionaries(fromPackages, toPackages, out var changedPackages))
            changes[graphNode] = changedPackages;
    }

    return changes;
}

