    {
        private string tag;

        /// <summary>
        /// Gets or sets the implementation of <see cref="IDocumentService"/>.
        /// </summary>
        [Inject]
        public IDocumentService DocumentService { get; set; }

        /// <summary>
        /// Gets or sets the <see cref="LoadingService"/>.
