        /// </summary>
        [Parameter]
        public string Tag
        {
            get => tag;
            set
            {
                if (value != tag)
                {
                    tag = value;
                    InvokeAsync(
                        async () =>
                            await TagChanged.InvokeAsync(tag));
                }
            }
        }

        /// <summary>
        /// Gets or sets the callback to notify on tag changes.
        /// </summary>
        [Parameter]
        public EventCallback<string> TagChanged { get; set; }

